@startuml

class Driver {
  + ID : long
  + Name : string
  + IsOnSickLeave : boolean
}

class Bus {
  + LicencePlate : string
  + IsInRepairShop : boolean
}

class BusRoute {
  + RouteNumber : int
}

class Shift {
  + ShiftType : string
}

class Assignment {
  + Date : date
}

class Schedule {
  + Date : date
}

Bus "0..*" -- "0..*" BusRoute : assigned to
Driver "0..*" -- "0..*" BusRoute : assigned to
Bus "1" -- "0..*" Assignment : is part of
BusRoute "1" -- "0..*" Assignment : has
Driver "1" -- "0..*" Assignment : works
Shift "1" -- "0..*" Assignment : occurs during
Assignment "0..*" -- "1" Schedule : belongs to
BusRoute "1" -- "1" Schedule : has

@enduml

